        // index == -1, upper == length, no appendToEnd
        assertEquals("Hello", WordUtils.abbreviate("Hello", 0, 5, "..."));
    }








}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen1Test {















    @Test
    public void testAbbreviate_SpaceAfterUpper() {
        // index > upper
        // "Hello World", lower=0, upper=3. index of space is 5. 5 > 3.
        // result: substring(0, 3) + "..."
        assertEquals("Hel...", WordUtils.abbreviate("Hello World", 0, 3, "..."));
    }






}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen1Test {

















    @Test
    public void testAbbreviate_SpaceWithinUpper() {
        // index <= upper (but not -1)
        // "Hello World", lower=0, upper=6. index of space is 5. 5 <= 6.
        // result: substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 6, "..."));
    }




}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen1Test {



















    @Test
    public void testAbbreviate_NullAppendToEnd() {
        // index == -1, upper < length, appendToEnd is null -> StringUtils.defaultString(null) is ""
        assertEquals("Hel", WordUtils.abbreviate("Hello", 0, 3, null));
    }


}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen1Test {





















    @Test
    public void testAbbreviate_SpaceAtLowerBoundary() {
        // index == lower
        // "Hello World", lower=5, upper=10. index is 5. 5 <= 10.
        // result: substring(0, 5) + "..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 5, 10, "..."));
    }
}
